window.KP_POSTS = [{"t":"A Anthropic estreia na bolsa com o maior IPO da história, mas o recorde só vale sem o lote extra da SpaceX","c":"Se Atualize","d":"19 de novembro de 2026","iso":"2026-11-19","s":"anthropic-ipo-83-dolares-81-bilhoes-nasdaq-ant-spacex","e":"A Anthropic levantou US$ 81,3 bilhões e chega à Nasdaq avaliada em cerca de US$ 1,5 trilhão. O recorde sobre a SpaceX vale na oferta base, e a empresa estreia ainda processada por editoras musicais.","min":3},{"t":"O Gemini 4 Neon custa mais por token que o Carbon, e mesmo assim o Google diz que ele sai 32% mais barato por tarefa","c":"Se Atualize","d":"19 de novembro de 2026","iso":"2026-11-19","s":"google-gemini-4-neon-api-3-dolares-32-por-cento-mais-barato-carbon","e":"O quarto modelo da família Gemini 4 em menos de dois meses chegou pela API paga, pelo Gemini para empresas e pelo app. O Google promete custo por tarefa menor que o do Carbon, mas o relatório completo de segurança ainda não saiu.","min":4},{"t":"O Grammy 2027 tem 100 categorias e revela os indicados hoje, e quem compõe o álbum vencedor passa a levar estatueta","c":"Se Atualize","d":"19 de novembro de 2026","iso":"2026-11-19","s":"grammy-2027-indicados-100-categorias-compositores-estatueta","e":"Os indicados ao 69º Grammy saem nesta segunda, com transmissão no YouTube a partir das 9h45 de Brasília. A edição volta a ter 100 categorias e, pela primeira vez, dá estatueta a quem compôs o álbum vencedor na maioria das categorias de gênero.","min":3},{"t":"O Instagram liberou link de afiliado da Amazon dentro do reel e não fica com nada da venda, mas por enquanto só nos EUA","c":"Se Atualize","d":"19 de novembro de 2026","iso":"2026-11-19","s":"instagram-links-afiliado-amazon-reels-30-produtos-eua","e":"O Instagram ligou a conta de afiliado da Amazon aos reels e posts. A empresa diz que o link dentro do conteúdo recebe o dobro de cliques do link da bio e que não cobra nada sobre a venda. Por enquanto, o recurso vale só nos Estados Unidos.","min":4},{"t":"As marcas vão gastar US$ 116 bilhões com creators em 2026, e o dinheiro está saindo da TV e das agências","c":"Se Atualize","d":"19 de novembro de 2026","iso":"2026-11-19","s":"madison-wall-creators-us-116-bilhoes-anunciantes-2026-tv-agencias","e":"O relatório da consultoria de Brian Wieser mostra o gasto das marcas com creators crescendo 15% este ano, com a mídia paga como maior fatia. Quase não entra verba nova: o dinheiro sai da TV, da rede social e das produtoras. O Brasil fica com 2%.","min":4},{"t":"O Spotify liberou pra todo artista a ferramenta que barra lançamento falso no perfil, mas por padrão a faixa vai ao ar se ele não fizer nada","c":"Se Atualize","d":"19 de novembro de 2026","iso":"2026-11-19","s":"spotify-artist-profile-protection-todos-artistas-lancamento-falso","e":"Depois de um teste com milhares de artistas, o Spotify abriu pra todo mundo a ferramenta que tira do perfil a música que não é sua. O problema é que agora a vigilância fica por conta do próprio artista.","min":4},{"t":"O Spotify diz que ver o clipe inteiro faz o fã tocar a música 64% mais, e o número saiu num texto patrocinado pelo próprio Spotify","c":"Se Atualize","d":"19 de novembro de 2026","iso":"2026-11-19","s":"spotify-clipes-64-por-cento-mais-streams-tres-semanas-2026","e":"O Spotify fez o balanço de um ano investindo em clipe e repetiu o seu dado favorito: quem vê o vídeo inteiro ouve a faixa 64% mais. O número é da própria empresa, saiu num espaço patrocinado e ninguém de fora conferiu.","min":4},{"t":"A Amazon Music criou o primeiro programa pra bancar compositor, e não contou quanto vai pagar","c":"Se Atualize","d":"15 de novembro de 2026","iso":"2026-11-15","s":"amazon-music-breakthrough-songwriters-amma-tre-jean-marie-carrie-k","e":"Depois de seis anos apoiando cantores, a Amazon Music criou um programa pra quem escreve as músicas. Os três primeiros já têm créditos com Olivia Dean, Noah Kahan e Little Mix, e o valor do fundo não foi divulgado.","min":3},{"t":"Uma agência de Porto Alegre abriu um estúdio só de IA generativa, e vai vender produção até pra marca que não é cliente dela","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"agencia-global-porto-alegre-global-studio-ia-generativa-producao","e":"A Global, de Porto Alegre, lançou em agosto o Global Studio, estúdio de produção com IA generativa que já atendeu Docile, Fruki e Elev. O detalhe mais importante: ele vende produção até pra marca que não é cliente da agência.","min":4},{"t":"A OpenAI diz que o ChatGPT já tem 20% do volume de buscas do Google, mas não contou de onde tirou o número do Google","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"chatgpt-20-por-cento-volume-buscas-google-openai-adam-fry","e":"A OpenAI afirma que o ChatGPT já soma 20% do volume de consultas do Google, sem dizer de onde tirou o número do Google. Ahrefs e seoClarity calculam bem menos, e o Google ainda manda cerca de 190 vezes mais visitas pros sites.","min":4},{"t":"A ElevenLabs agora ajuda a escrever o padrão que vai identificar música feita por IA, e ele sai no início de 2027","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"elevenlabs-ddex-membro-pleno-padrao-gai-d-musica-ia-2027","e":"Em 5 de novembro, o DDEX anunciou a ElevenLabs como membro pleno, a primeira empresa de IA nessa condição segundo a entidade. Ela chega na reta final do GAI-D, o padrão que vai dizer como declarar música feita por IA.","min":4},{"t":"Um hit com 206 milhões de streams começou como música feita no Suno, e os streamings não mostram aviso de IA","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"hugel-movin-to-the-sun-suno-206-milhoes-streams-ia-rotulo","e":"A faixa de Hugel, Ultra Naté e Imael Angel virou hit mundial depois de nascer no Suno. O DJ diz que quase tudo foi feito por humanos, e as plataformas não sabem em qual gaveta colocar a música.","min":4},{"t":"As marcas aprovam a ideia da agência e passam a execução pro creator, e quem fica sem a receita de produção são as independentes","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"marcas-contratam-creators-direto-agencias-independentes-producao","e":"Reportagem do Ad Age, publicada pelo Meio & Mensagem em 5 de novembro, mostra marcas pegando o conceito da agência e repassando a creators já contratados. As independentes perdem a produção e começam a mudar a forma de vender e cobrar.","min":4},{"t":"Funcionários da OpenAI avisaram por anos que a segurança era fraca, e em outubro um engenheiro foi preso acusado de esconder um gravador no papel higiênico","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"openai-funcionarios-alertas-seguranca-reuters-monorepo-alfozan","e":"Cinco fontes contaram à Reuters que a OpenAI ignorou por anos alertas internos sobre segurança fraca. A empresa contesta parte do relato, mudou um quarto dos engenheiros de produção de função e promete um novo mutirão de proteção.","min":4},{"t":"A OpenAI promete imagem 50% mais rápida no ChatGPT pela segunda vez em dois meses, e agora ele também faz GIF","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"openai-images-2-6-chatgpt-gif-50-por-cento-mais-rapido-flare-sunburst","e":"A OpenAI lançou o Images 2.6 em 4 de novembro, com GIF animado no ChatGPT, duas versões na API e geração 50% mais rápida. É a segunda promessa de 50% em dois meses, e a empresa diz que já são 4 bilhões de imagens por semana.","min":4},{"t":"O juiz reconheceu o prejuízo que o resumo de IA do Google causa aos sites e arquivou o caso mesmo assim, e agora a dona da Billboard recorre","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"penske-billboard-recorre-google-ai-overviews-juiz-mehta-arquivou","e":"O juiz Amit Mehta arquivou o processo antitruste da Penske Media contra os resumos de IA do Google, mesmo dizendo que não trata o prejuízo dos sites com leveza. Agora a dona da Billboard leva o caso adiante, e a Chegg foi junto.","min":4},{"t":"A Riachuelo escolheu João Gomes pro Natal, e ele já é o rosto da Casas Bahia e da Reserva no mesmo ano","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"riachuelo-joao-gomes-natal-ria-junto-casas-bahia-reserva","e":"A Riachuelo anunciou João Gomes como rosto do fim de ano, cantando uma música feita pra campanha. É o terceiro varejista a apostar nele em 2026, e isso diz muito sobre o peso do Nordeste no consumo e sobre o risco de dividir o mesmo rosto.","min":4},{"t":"O Wrapped teve 635 milhões de compartilhamentos em 2025, e o artista tem só até 13 de novembro pra garantir espaço no deste ano","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"spotify-wrapped-2026-artistas-prazo-13-novembro-635-milhoes","e":"A Music Ally e o Spotify for Artists publicaram o guia do Wrapped 2026. O artista pode gravar um vídeo de até 30 segundos pros fãs e subir performances, mas o prazo mudou no meio do caminho e aparecer no Wrapped não é garantido.","min":3},{"t":"O WhatsApp começou a transformar telefone, endereço e data das conversas em atalho, e a Meta nem anunciou a novidade","c":"Se Atualize","d":"14 de novembro de 2026","iso":"2026-11-14","s":"whatsapp-atalhos-telefone-endereco-data-mensagens-android-iphone","e":"Em 2 de novembro, o WABetaInfo mostrou que o WhatsApp passou a transformar telefone, endereço, data e e-mail das mensagens em atalhos pra ligar, abrir o mapa ou criar evento. A liberação é gradual, e a Meta não fez anúncio oficial.","min":4},{"t":"A Amazon chamou de profundamente falha a régua que usa pra medir IA nos engenheiros, e avisou que vai continuar usando","c":"Se Atualize","d":"2 de novembro de 2026","iso":"2026-11-02","s":"amazon-memo-ia-engenheiros-tokens-metrica-falha-tokenmaxxing","e":"Em 27 de outubro, a Amazon publicou um memo em que admite que medir IA por tokens e código é falho, cinco meses depois de fechar um ranking interno que engenheiros inflavam de propósito. Os números ficam, mas deixam de ser meta.","min":4},{"t":"As cinco big techs vão gastar até US$ 753 bilhões em IA, e a Alphabet perdeu US$ 500 bilhões em valor num único dia ao mostrar a conta","c":"Se Atualize","d":"2 de novembro de 2026","iso":"2026-11-02","s":"big-techs-us-753-bilhoes-ia-alphabet-perde-500-bilhoes-balanco","e":"Os planos de investimento em IA das cinco maiores big techs somam até US$ 753 bilhões. A bolsa reagiu mal: a Alphabet teve o pior dia da história e a Amazon caiu, apesar de receitas em alta e de a nuvem crescer forte.","min":3},{"t":"O alerta do Ecad contra ISRC gerado por agregadoras circula como novidade, mas é de 2021 e a regra mudou em 2022","c":"Se Atualize","d":"2 de novembro de 2026","iso":"2026-11-02","s":"ecad-alerta-isrc-irregular-agregadoras-2021-regra-mudou-2022","e":"O comunicado da gestão coletiva sobre ISRC irregular voltou a circular, mas a cobertura é de 12 de maio de 2021. Em 2022 a regra mudou, e quem lê só o alerta pode agir com informação velha.","min":3},{"t":"O Google nunca faturou tanto, e mesmo assim admitiu que cada pergunta feita ao AI Mode rende menos que uma busca comum","c":"Se Atualize","d":"2 de novembro de 2026","iso":"2026-11-02","s":"google-receita-recorde-3t26-ai-mode-rende-menos-anuncio-brasil","e":"Receita recorde de US$ 127,6 bilhões, busca crescendo 12% depois de 19% e 17%, e um chefe de negócios admitindo que a pergunta feita à IA rende menos. Ao mesmo tempo, o Google prepara anúncio no AI Mode pro Brasil ainda em 2026.","min":4},{"t":"A OpenAI processa o Google na disputa por IA, mas agora quer comprar os chips dele, e ninguém confirmou o negócio","c":"Se Atualize","d":"2 de novembro de 2026","iso":"2026-11-02","s":"openai-quer-comprar-chips-tpu-google-the-information","e":"A OpenAI estuda comprar os chips de IA do Google, que hoje aluga, segundo o The Information. Não há preço, quantidade nem confirmação das empresas, e o chip próprio com a Broadcom segue em desenvolvimento.","min":3},{"t":"O Spotify quer cobrar de US$ 4 a US$ 5 por mês pelo remix com IA no início de 2027, mas Sony e Warner ainda não assinaram","c":"Se Atualize","d":"2 de novembro de 2026","iso":"2026-11-02","s":"spotify-remix-ia-2027-adicional-4-5-dolares-universal-sony-warner","e":"O Financial Times diz que o Spotify quer lançar o remix com IA no início de 2027, por US$ 4 a US$ 5 a mais por mês. Três licenciadoras já assinaram, duas majors ainda não, e data e preço não são oficiais.","min":3},{"t":"A Suno liberou a criação de música dentro do Claude, mesmo com a Anthropic e a própria Suno sendo processadas pelas gravadoras","c":"Se Atualize","d":"2 de novembro de 2026","iso":"2026-11-02","s":"suno-mcp-servidor-musica-dentro-claude-chatgpt-gemini","e":"A Suno lançou em acesso antecipado um servidor MCP que cria música dentro de Claude, ChatGPT, Gemini, Claude Code e Cursor, gastando créditos da conta. O lançamento chega no meio dos processos que envolvem a Suno e a Anthropic.","min":4},{"t":"O YouTube Music e o Premium passaram de 150 milhões de assinantes, e a conta inclui gente que ainda nem começou a pagar","c":"Se Atualize","d":"2 de novembro de 2026","iso":"2026-11-02","s":"youtube-music-premium-150-milhoes-assinantes-alphabet-q3-2026","e":"O YouTube Music e o Premium somam mais de 150 milhões de assinantes, 25 milhões a mais que em março de 2025. O número inclui testes grátis, e a TV da sala já seria um terço da receita de anúncios.","min":3},{"t":"Quem compõe música de jogo costuma receber uma vez só, e um executivo chamou esse catálogo de Ferrari parada na garagem","c":"Se Atualize","d":"28 de outubro de 2026","iso":"2026-10-28","s":"gamesoundcon-2026-editora-jogos-ativo-nao-monetizado-royalties","e":"Em Burbank, um painel da GameSoundCon defendeu royalties vitalícios pra quem compõe música de jogos. A tese é forte, mas vem de executivos do setor e de uma matéria feita em parceria com a Materia Music, que mediou o debate.","min":3},{"t":"Gravadoras já processaram a Kroger, a Quince e a dona da Ray-Ban por música em post, e o teto chega a US$ 150 mil por obra","c":"Se Atualize","d":"28 de outubro de 2026","iso":"2026-10-28","s":"gravadoras-processam-marcas-musica-redes-sociais-us-150-mil-obra","e":"Sony processou a Kroger por 392 usos, a Warner foi atrás da dona da Ray-Ban por 427 obras, e a UMG processou a Quince. O padrão é o mesmo: a música da rede social não vale como licença pra marca.","min":3},{"t":"A Meta passou anos dizendo que vídeo longo atrapalhava a rede, e agora testa vídeos de até 90 minutos, inclusive com criadores brasileiros","c":"Se Atualize","d":"28 de outubro de 2026","iso":"2026-10-28","s":"meta-features-videos-horizontais-90-minutos-podcasters-youtube","e":"O formato Features aceita vídeos horizontais de até 90 minutos e está em teste com poucos criadores nos EUA e no Brasil. A Meta não vai repartir receita de anúncios por enquanto, e é aí que o YouTube segue na frente.","min":3},{"t":"A OpenAI diz que a IA refutou uma hipótese famosa da computação, mas a prova de física nem foi publicada","c":"Se Atualize","d":"28 de outubro de 2026","iso":"2026-10-28","s":"openai-ia-provas-matematica-fisica-eth-yang-mills-revisao","e":"A OpenAI anunciou três resultados de pesquisa atribuídos aos seus modelos, de matemática à física. A empresa mostrou o material de dois e segurou o terceiro, enquanto especialistas de fora ainda tentam confirmar tudo.","min":3},{"t":"O Canva criou a própria IA de imagem treinada com templates, e a aposta é que ela planeje o layout antes de desenhar","c":"Se Atualize","d":"25 de outubro de 2026","iso":"2026-10-25","s":"canva-craft-primeira-ia-propria-imagem-planeja-layout-2k","e":"O Craft é o primeiro modelo de imagem treinado pelo Canva. Em vez de partir de fotos, aprendeu com templates da própria biblioteca e divide o trabalho em duas etapas: planeja a composição e só depois renderiza.","min":3},{"t":"A CoreWeave tomou até US$ 8,5 bilhões com chips de IA como garantia, mas quem paga a dívida é o contrato com o cliente","c":"Se Atualize","d":"25 de outubro de 2026","iso":"2026-10-25","s":"coreweave-credito-8-5-bilhoes-chips-ia-garantia-blackstone","e":"Chips de IA viraram garantia de crédito bilionário. A CoreWeave tem uma linha de até US$ 8,5 bilhões com a Blackstone, mas o dinheiro volta pelo contrato com o cliente, e o prazo de validade do chip é a dúvida.","min":3},{"t":"Quem cuida da obra de Elvis Presley processou a Anthropic por 274 músicas, e a conta pode passar de US$ 41 milhões","c":"Se Atualize","d":"25 de outubro de 2026","iso":"2026-10-25","s":"elvis-presley-processa-anthropic-274-musicas-41-milhoes-claude","e":"Uma subsidiária da Authentic Brands Group e outros donos de direitos de Elvis entraram com ação contra a Anthropic em 23 de outubro. São 274 músicas, e o valor máximo previsto em lei chega a cerca de US$ 41,1 milhões.","min":3},{"t":"O Mercado Livre lançou uma IA que decide onde seu anúncio aparece, até na Netflix e no Disney+, com dados de 131 milhões de compradores","c":"Se Atualize","d":"25 de outubro de 2026","iso":"2026-10-25","s":"mercado-ads-engage-plus-ia-topo-funil-131-milhoes-compradores","e":"O Engage+ usa sinais de mais de 131 milhões de compradores do Mercado Livre pra prever interesse e escolher onde o anúncio passa, dentro e fora do marketplace. Já está no Brasil, mas os números de resultado vêm do próprio Mercado Ads.","min":3},{"t":"As redes passaram anos decidindo o que você vê, e agora todas ao mesmo tempo estão te devolvendo o controle do feed","c":"Se Atualize","d":"25 de outubro de 2026","iso":"2026-10-25","s":"redes-sociais-controle-feed-seu-algoritmo-tiktok-youtube-abas","e":"Depois de anos empurrando recomendação automática, as grandes redes agora deixam o usuário ajustar o próprio feed. Pra quem depende de alcance orgânico, a mudança vale uma atenção maior do que parece.","min":3},{"t":"Ex-executivos do TikTok levantaram US$ 11 milhões pra uma IA que cria a trilha do vídeo sozinha, e ainda não fecharam acordo com as gravadoras","c":"Se Atualize","d":"25 de outubro de 2026","iso":"2026-10-25","s":"sonilo-capta-11-milhoes-musica-ia-video-ex-tiktok-shutterstock","e":"A Sonilo gera trilha e efeito sonoro a partir do vídeo, tem a Shutterstock como parceira de licenciamento e US$ 11 milhões em caixa. O que ainda falta é fechar os contratos com quem é dono das músicas.","min":4},{"t":"O Spotify diz que agora é um agente de IA, e que a música e os dados de gosto não saem de dentro dele mesmo quando você pede por outro app","c":"Se Atualize","d":"25 de outubro de 2026","iso":"2026-10-25","s":"spotify-agente-ia-soderstrom-chatgpt-muse-descoberta-musica","e":"Na teleconferência de resultados, o co-CEO do Spotify disse que a plataforma virou um agente de IA e já funciona dentro do ChatGPT e do Muse da Meta. Segundo ele, quem toca a música e guarda o gosto do ouvinte continua sendo o Spotify.","min":3},{"t":"O Spotify passou a exigir QR code no plano família e bloqueia por 12 meses quem não provar que mora junto, mas chama isso de melhoria de rotina","c":"Se Atualize","d":"25 de outubro de 2026","iso":"2026-10-25","s":"spotify-plano-familia-qr-code-bloqueio-12-meses-norstrom","e":"O co-CEO Alex Norström confirmou a checagem por QR code no plano família, que já responde por uma fatia grande dos assinantes. Quem não comprovar que mora com o titular em sete dias perde o acesso a planos compartilhados por 12 meses.","min":3},{"t":"Globo, Google e Netflix pagaram a mesma empresa pra medir atenção nos anúncios, e agora ela diz que os números não podem ser comparados","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"amplified-painel-atencao-brasil-2027-globo-youtube-netflix","e":"Globoplay com quase 75%, Netflix com 67%, YouTube com 61,3%. Os três números vieram da mesma empresa, a Amplified, que agora diz que eles não cabem no mesmo ranking e prepara um painel compartilhado pra 2027.","min":3},{"t":"A Anthropic lançou um agente que trabalha com o app fechado, e tem coisa que ele não faz nem com a sua autorização","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"anthropic-claude-duet-agente-trabalha-app-fechado-6-mil-conectores","e":"A Anthropic apresentou o Claude Duet, um agente que acompanha seus apps de trabalho, se liga a mais de 6 mil conectores e continua rodando na nuvem quando você sai. Mover dinheiro entre contas ficou proibido, mesmo com o seu ok.","min":4},{"t":"Mais da metade dos brasileiros acha anúncio irritante, mas é a oferta nas redes sociais que mais faz gente comprar","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"black-friday-2026-saturacao-anuncios-yougov-58-por-cento","e":"A YouGov ouviu cerca de 12 mil brasileiros: 58,4% se sentem bombardeados por anúncios e 53,3% acham a propaganda irritante. Mesmo assim, 30,3% compraram por oferta vista em rede social. Magalu, Amazon e Samsung já mudaram a rota.","min":3},{"t":"Até 85% dos plays de música feita por IA na Deezer eram fraude, e foi esse dado que levou um deputado a pedir a consulta dos EUA","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"deezer-85-por-cento-fraude-musica-ia-consulta-copyright-office-eua","e":"A carta do deputado americano falava de IA e usava um dado da Deezer: até 85% dos plays de faixas feitas por IA eram fraude. A consulta aberta em 7 de outubro olha pro método do golpe, e isso muda a conversa pra distribuidora e artista.","min":4},{"t":"A Galinha Pintadinha começou num clipe de YouTube e, 20 anos depois, virou filme no cinema e área de R$ 50 milhões no Beto Carrero","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"galinha-pintadinha-mundo-bita-licenciamento-beto-carrero-50-milhoes","e":"A Galinha Pintadinha e o Mundo Bita nasceram de canção no YouTube e hoje vendem lancheira, xampu, calçado, ingresso de show e de cinema. O clipe gratuito virou vitrine de um negócio que cresce longe da tela.","min":3},{"t":"Uma briga de trânsito de 1999 virou dívida de R$ 230 mil, e a Justiça foi buscar o dinheiro nos royalties de Maurício Mattar","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"mauricio-mattar-penhora-royalties-ecad-spotify-r-230-mil","e":"Pra pagar uma indenização que passa de R$ 230 mil, a Justiça mandou procurar os rendimentos musicais de Maurício Mattar no Ecad, na Abramus, na UBC, no Spotify e em outras plataformas. A penhora foi limitada a 30%.","min":4},{"t":"A brasileira Moises virou o estúdio de IA do SoundCloud, e a promessa é justamente não fazer a música por você","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"moises-soundcloud-parceria-ia-stems-mixagem-publicar","e":"Desde 21 de outubro, artistas do SoundCloud podem levar faixas próprias pro Moises, retrabalhar com IA e publicar de volta. O anúncio fala em 150 milhões de artistas, mas os números das próprias empresas somam cerca de 120 milhões.","min":3},{"t":"O Google começou a vender o GPT-6, rival direto do Gemini, dentro da própria nuvem","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"openai-gpt-6-google-cloud-model-garden-astra-sol-luna","e":"A OpenAI levou três modelos da família GPT-6 pro catálogo de IA do Google Cloud, em prévia fechada pra empresas. A exclusividade da Microsoft já tinha caído em abril. O Google agora vende o rival do Gemini, e o cliente paga tudo na mesma fatura.","min":3},{"t":"A Raye teve 1,8 milhão de cadastros pra um show de 5 mil lugares, e robôs de IA inflaram boa parte da fila","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"raye-1-8-milhao-cadastros-robos-ia-5-mil-lugares-metricas-fas","e":"A cantora Raye cancelou a pré-venda de um show de 5 mil lugares depois de receber 1,8 milhão de cadastros, muitos feitos por robôs. A MIDiA usou o caso pra propor outro jeito de medir a relação entre fã e artista.","min":3},{"t":"A Suno já paga a Warner pra treinar IA, e a Reservoir usou justamente isso pra processar a empresa","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"reservoir-processa-suno-anthropic-1050-musicas-853-letras-treino-ia","e":"A Reservoir entrou com duas ações na Califórnia contra a Suno e a Anthropic. O argumento mais afiado vem dos próprios acordos da Suno: se já existe mercado pra licenciar música pra IA, quem não paga não tem desculpa.","min":4},{"t":"A Runway saltou de 77 pra 900 anúncios por semana com a própria IA, e agora quer vender essa máquina pra quem anuncia","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"runway-ads-900-anuncios-semana-ia-criativa-agencias","e":"A Runway diz que foi de 77 pra cerca de 900 anúncios por semana com a própria ferramenta e lançou o Runway Ads. Canva, Figma, ElevenLabs e Typeface fazem o mesmo movimento: sair da geração de imagem e ocupar a campanha inteira.","min":4},{"t":"A Sony quer encher show virtual com fã de mentira, e o plano é que ninguém perceba a diferença","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"sony-patente-fas-artificiais-shows-virtuais-npc-plateia","e":"A dona do PlayStation pediu patente de um sistema que preenche a plateia de shows virtuais com personagens de computador que imitam fãs reais. O objetivo declarado é que eles não pareçam robôs, e isso mexe com a forma de medir público.","min":4},{"t":"A SoundExchange repassa quase US$ 1 bilhão por ano aos artistas, mas a Justiça americana ainda não sabe se ela pode processar quem não paga","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"soundexchange-sonos-3-4-milhoes-suspenso-direito-processar-siriusxm","e":"A ação da SoundExchange contra a Sonos saiu da lista ativa de um tribunal da Califórnia e só volta depois da decisão no caso SiriusXM, que vale US$ 150 milhões. A pergunta é se quem arrecada royalty tem o direito de cobrar o devedor na Justiça.","min":4},{"t":"O Spotify chegou a 306 milhões de assinantes, e a América Latina está a um ponto de passar a América do Norte","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"spotify-306-milhoes-assinantes-america-latina-24-por-cento","e":"O Spotify fechou o trimestre com 306 milhões de assinantes Premium e receita de 4,97 bilhões de euros. A América Latina chegou a 24% da base paga e pode passar a América do Norte em volume, mas o dinheiro por assinante ainda é bem menor por aqui.","min":3},{"t":"O Spotify tirou mais de 50 milhões de faixas de IA e spam das recomendações só em 2026, e elas continuam no app","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"spotify-50-milhoes-faixas-ia-spam-fora-recomendacoes-2026","e":"Mais de 50 milhões de faixas de IA e spam saíram das recomendações do Spotify em 2026, sem serem apagadas. Música com fortes indícios de IA tem dez vezes mais chance de ficar abaixo das mil reproduções que pagam royalty.","min":4},{"t":"O streaming passou de 990 bilhões de plays em 2026, e mesmo assim a música nova está tocando menos","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"streaming-990-bilhoes-reproducoes-2026-catalogo-luminate-abramus","e":"Dados da Luminate divulgados pela Abramus somam 990,3 bilhões de streams em 2026, mas as faixas recentes caíram 3,6% e o catálogo subiu 7,1%. O número também não é global, e isso muda a leitura.","min":3},{"t":"A Suno quer obrigar a entidade que paga os compositores nos EUA a entregar cinco anos de dados de streaming pra se defender das gravadoras","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"suno-mlc-dados-streaming-2021-processo-gravadoras-udio","e":"Processada pelas gravadoras, a Suno quer usar os dados da MLC, que cobra o direito mecânico nos EUA, pra provar que a IA não tirou mercado de ninguém. A MLC chegou a aceitar entregar terabytes de dados, segundo a Suno, e depois voltou atrás.","min":4},{"t":"Faltou juiz na Suprema Corte dos EUA, e um compositor venceu as gigantes da música pelos direitos mundiais de uma canção dos anos 1960","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"suprema-corte-eua-vetter-double-shot-rescisao-direitos-mundiais","e":"Quatro juízes se declararam impedidos, a Suprema Corte ficou sem quórum e a decisão que devolveu ao compositor Cyril Vetter os direitos de Double Shot no mundo todo ficou de pé. Vale como vitória, mas não como precedente nacional.","min":3},{"t":"A Universal virou a primeira major a deixar uma IA mexer nas suas músicas no meio do jogo, num app que até agora só tinha independentes","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"universal-music-tyger-ia-adapta-musica-games-primeira-major","e":"A Tyger usa IA pra fazer a música acompanhar o que acontece na tela durante o jogo e tinha mais de 400 mil faixas, quase todas de independentes. Agora a Universal entrou, e o valor do acordo não foi divulgado.","min":4},{"t":"A Warner juntou gravação e composição numa só equipe de sincronização, e quer que a marca peça a música uma vez só","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"warner-music-une-sync-gravacao-editora-ron-broitman","e":"A Warner Music juntou numa divisão só as equipes que licenciam gravação e composição pra anúncio, filme e série. A promessa é um contato único e liberação mais rápida, num mercado de sync que encolheu 2% no lado das gravadoras em 2025.","min":4},{"t":"A Warrior, que vende anúncio em live de game, vai atrás de esporte e reality mesmo com os games trazendo mais de 70% da receita","c":"Se Atualize","d":"24 de outubro de 2026","iso":"2026-10-24","s":"warrior-streaming-media-4800-streamers-esportes-reality-podcasts","e":"A Warrior Streaming Media, que coloca anúncio dentro de transmissões ao vivo, vai atuar também em esportes, reality, podcasts e cultura pop. O CEO diz que foi o mercado que puxou a mudança, mesmo com mais de 70% da audiência e do faturamento ainda vindo dos games.","min":4},{"t":"O Ceará deve render até R$ 30 milhões em direitos autorais em 2026, mas quase 180 prefeituras ainda não pagaram o Ecad","c":"Se Atualize","d":"23 de outubro de 2026","iso":"2026-10-23","s":"ecad-ceara-arrecadacao-2026-r-30-milhoes-alta-15-por-cento","e":"O Ecad projeta até R$ 30 milhões no Ceará em 2026, com 85% indo direto aos titulares. O comércio paga mais que os shows, e só 24 de quase 180 prefeituras notificadas regularizaram a dívida.","min":3},{"t":"A Musixmatch, que começou mostrando letra de música, agora vai cuidar de mais de US$ 400 milhões em royalties por ano","c":"Se Atualize","d":"23 de outubro de 2026","iso":"2026-10-23","s":"musixmatch-music-reports-400-milhoes-royalties-por-ano-neutralidade","e":"A Musixmatch comprou a Music Reports e passa a controlar uma operação de mais de US$ 400 milhões em royalties por ano, com 500 clientes. A empresa que vende dados pros apps e detecção de cópia pra Suno agora também guarda o registro de quem é dono de cada música.","min":4},{"t":"Música antiga já é quase metade do Top 200 global do Spotify, e lançamento novo virou jogo mais difícil","c":"Se Atualize","d":"20 de outubro de 2026","iso":"2026-10-20","s":"catalogo-domina-top-200-spotify-45-por-cento-streams-2026","e":"Catálogo com mais de três anos já responde por 45,1% das streams do Top 200 global do Spotify em 2026, enquanto as faixas novas perderam quase um quarto dos plays. O que isso muda pra quem lança música.","min":4},{"t":"O Instagram colocou uma IA pra ler os números dos seus Reels e dizer o que postar em seguida","c":"Se Atualize","d":"20 de outubro de 2026","iso":"2026-10-20","s":"instagram-edits-assistant-ia-analisa-reels-criadores","e":"O Edits Assistant, do Instagram, lê alcance, retenção e engajamento da sua conta e sugere o que postar: ganchos, legendas, roteiros e áudios. Grátis com limite diário, por ora só nos Estados Unidos.","min":3},{"t":"A Musixmatch, das letras de música, comprou a dona do Songdex e quer virar plataforma de royalties","c":"Se Atualize","d":"20 de outubro de 2026","iso":"2026-10-20","s":"musixmatch-compra-music-reports-songdex-primeira-aquisicao","e":"A Musixmatch comprou a Music Reports, dona do Songdex, e leva junto a Blokur. É a primeira aquisição em 16 anos e o passo pra sair das letras e virar plataforma completa de direitos e royalties.","min":3},{"t":"A Meta liberou um modelo de IA de 816 bilhões de parâmetros com pesos abertos, e ele roda em Mac Studio","c":"Se Atualize","d":"17 de outubro de 2026","iso":"2026-10-17","s":"meta-muse-spark-open-modelo-aberto-816b-roda-no-mac","e":"O Muse Spark Open, da Meta, tem 816 bilhões de parâmetros, 1 milhão de tokens de contexto e pesos abertos. Roda em Mac Studio, mas só em versões comprimidas e com mais de 300 GB de memória.","min":3},{"t":"A Warner Music processou a dona da Ray-Ban por usar 427 músicas em anúncio sem licença, e a conta pode chegar a US$ 64 milhões","c":"Se Atualize","d":"17 de outubro de 2026","iso":"2026-10-17","s":"warner-music-processa-dona-da-ray-ban-427-musicas-anuncios","e":"A Warner Music processou empresas do grupo Luxottica, dona de Ray-Ban e Oakley, por 427 obras usadas sem licença em anúncios nas redes. O teto de US$ 64 milhões é cálculo de dano máximo, não valor cobrado.","min":3},{"t":"O YouTube Music começou a carimbar música feita por IA, e quem decide o carimbo é o próprio selo","c":"Se Atualize","d":"17 de outubro de 2026","iso":"2026-10-17","s":"youtube-music-selo-musica-ia-fully-gen-ai","e":"O YouTube Music começou a rotular faixas feitas por IA como Fully Gen AI ou Partly Gen AI. A declaração vem do selo ou distribuidora, via DDEX ou planilha, e o que não for declarado vira 'desconhecido'.","min":4},{"t":"A Siri finalmente toca Spotify sem você dizer 'no Spotify', mas só em inglês e fora da Europa","c":"Se Atualize","d":"14 de outubro de 2026","iso":"2026-10-14","s":"spotify-siri-ios-27-sem-dizer-no-spotify","e":"Quem usa iOS 27 pode pedir música à Siri sem dizer 'no Spotify'. Mas precisa de iPhone 15 Pro ou mais novo, não vale na União Europeia e, por enquanto, só funciona em inglês.","min":2},{"t":"O Escritório de Direitos Autorais dos EUA abriu consulta pública sobre fraude em streaming um dia depois da condenação de Michael Smith","c":"Se Atualize","d":"14 de outubro de 2026","iso":"2026-10-14","s":"us-copyright-office-consulta-fraude-streaming","e":"O U.S. Copyright Office abriu consulta pública sobre fraude em streaming, um dia depois da condenação de Michael Smith. Pede dados sobre bots, click farms e playlist stuffing, com comentários até 23 de novembro.","min":3},{"t":"A Meta quer que o agente de IA monte, compre e pague o anúncio sozinho, mas boa parte ainda está em teste","c":"Se Atualize","d":"12 de outubro de 2026","iso":"2026-10-12","s":"meta-advertising-week-2026-ads-mcp-checkout","e":"A Meta ampliou o Ads Creative Studio, integrou o Ads MCP Server a parceiros como Snowflake e Triple Whale e anunciou testes de checkout no Meta AI com Stripe, PayPal, Shopify e Adyen. O que está no ar e o que está em teste varia por fonte.","min":3},{"t":"O Spotify liga os audiobooks no Brasil em 15 de outubro, com 12 horas por mês incluídas no Premium","c":"Se Atualize","d":"12 de outubro de 2026","iso":"2026-10-12","s":"spotify-audiobooks-brasil-15-outubro","e":"O Spotify leva os audiobooks de 22 pra mais de 180 mercados até o fim do ano. No Brasil, a liberação é em 15 de outubro, com 12 horas por mês incluídas no Premium e um catálogo em português de mais de 6 mil títulos.","min":3},{"t":"O Spotify começou a vender pra outras empresas as ferramentas que usa pra construir o próprio app","c":"Se Atualize","d":"12 de outubro de 2026","iso":"2026-10-12","s":"spotify-technology-vende-ferramentas-internas","e":"O technology.spotify.com reúne Backstage, Confidence, Portal e Xirp, ferramentas internas do Spotify agora oferecidas a outras empresas. O site não mostra preço, e o Spotify não divulga quanto essa área fatura.","min":2},{"t":"O Google lançou um agente que vira colega de trabalho, com e-mail próprio, e roda até dentro do Microsoft 365 e do Slack","c":"Se Atualize","d":"09 de outubro de 2026","iso":"2026-10-09","s":"google-cloud-gemini-agent-empresas","e":"O Google Cloud apresentou o Gemini agent, que responde, executa tarefas e escreve código, e roda no Workspace, no Microsoft 365 e no Slack. Aceita modelos Gemini e Claude e ainda está em prévia privada.","min":2},{"t":"A Meta e a Sierra anunciaram o protocolo pra agente de IA comprar por você, mas a especificação nem foi publicada","c":"Se Atualize","d":"09 de outubro de 2026","iso":"2026-10-09","s":"meta-sierra-personal-agent-protocol","e":"Sierra e Meta anunciaram o Personal Agent Protocol, padrão aberto em OAuth pra agentes de IA agirem em sites e serviços de empresas. Ainda não há especificação, licença nem órgão de governança, e pagamento ficou pra depois.","min":2},{"t":"A OpenAI cortou pela metade o preço do GPT-6 e botou o Luna no plano gratuito","c":"Se Atualize","d":"09 de outubro de 2026","iso":"2026-10-09","s":"openai-gpt-6-sol-luna-preco-pela-metade","e":"O GPT-6 Sol custa US$ 2 por milhão de tokens de entrada e o Luna, US$ 0,10, metade do preço de referência. No ChatGPT, o Luna chega a quem não paga. As fontes divergem sobre datas e onde cada modelo aparece.","min":3},{"t":"O TikTok Shop vai gastar R$ 100 milhões em cupons na Black Friday brasileira, e a aposta principal é a live","c":"Se Atualize","d":"09 de outubro de 2026","iso":"2026-10-09","s":"tiktok-shop-brasil-black-friday-100-milhoes","e":"O TikTok Shop Brasil vai investir R$ 100 milhões em cupons, de 27 de outubro a 12 de dezembro, com até 70% de desconto. Segundo a empresa, uma live com demonstração de produto converte de R$ 50 mil a R$ 100 mil.","min":2},{"t":"A Futurecom 2026 espera 30 mil pessoas em São Paulo, e o assunto que domina é IA agêntica","c":"Se Atualize","d":"07 de outubro de 2026","iso":"2026-10-07","s":"futurecom-2026-ia-agentica-sao-paulo","e":"A Futurecom 2026, de 6 a 8 de outubro em São Paulo, espera 30 mil visitantes, 300 marcas e 400 palestrantes. O tema central é IA agêntica: agentes autônomos, segurança e governança.","min":2},{"t":"A Itália abriu investigação contra a Suno por cláusulas que deixam a empresa mudar preço e cancelar conta sem aviso","c":"Se Atualize","d":"07 de outubro de 2026","iso":"2026-10-07","s":"italia-investiga-suno-termos-de-uso-abusivos","e":"A AGCM, da Itália, investiga se os termos de uso da Suno são abusivos: mudança unilateral de preço, cancelamento de conta sem aviso, arbitragem nos EUA e renúncia a direitos morais. Cinco dias antes, o CEO dizia que a empresa estava muito além de 2 milhões de assinantes.","min":3},{"t":"O homem que usou 10 mil contas falsas pra ouvir música feita por IA bilhões de vezes pegou 18 meses de prisão","c":"Se Atualize","d":"07 de outubro de 2026","iso":"2026-10-07","s":"michael-smith-condenado-fraude-streaming-ia","e":"Michael Smith foi condenado a 18 meses de prisão e ao confisco de US$ 8,09 milhões por usar até 10 mil contas falsas pra gerar bilhões de plays de música feita por IA. A promotoria pedia no mínimo 46 meses.","min":2},{"t":"A OpenAI vai mostrar anúncio enquanto o ChatGPT gera sua imagem, mas só pra quem não paga","c":"Se Atualize","d":"05 de outubro de 2026","iso":"2026-10-05","s":"chatgpt-anuncios-visuais-geracao-de-imagens","e":"A OpenAI vai testar anúncio visual enquanto o ChatGPT gera imagem, nos EUA, só pros planos Free e Go. Quem assina Plus, Pro, Business ou Enterprise fica de fora.","min":2},{"t":"O Instagram deixou artista impulsionar live em poucos toques, e o TikTok virou o QG do clipe da Taylor Swift","c":"Se Atualize","d":"05 de outubro de 2026","iso":"2026-10-05","s":"instagram-boost-live-artista-tiktok-patient-zero","e":"O Instagram liberou o impulsionamento de lives de artista direto no app, e o TikTok transformou o clipe de Patient Zero, da Taylor Swift, numa missão coletiva de fãs. As plataformas estão criando ferramenta nativa pra promover música.","min":3},{"t":"A Meta lançou um agente de IA que mexe no Shopify, no Stripe e no QuickBooks da sua loja","c":"Se Atualize","d":"05 de outubro de 2026","iso":"2026-10-05","s":"meta-muse-for-small-business-agente-pmes","e":"O Muse for Small Business, da Meta, conecta Shopify, Stripe, QuickBooks e Canva ao Instagram e à conta de anúncios pra analisar vendas e preparar conteúdo. O dono precisa aprovar tudo antes de publicar ou gastar.","min":3},{"t":"A Suno já passou muito de 2 milhões de assinantes, diz o CEO, que acha bom a IA musical ainda não ter regra firme","c":"Se Atualize","d":"05 de outubro de 2026","iso":"2026-10-05","s":"suno-muito-alem-2-milhoes-assinantes","e":"O CEO da Suno diz que a empresa passou muito dos 2 milhões de assinantes e dos US$ 300 milhões de receita de fevereiro, mas não deu número novo. Também acha bom a IA musical ainda não ter regra firme.","min":3},{"t":"O Gemini 4 Argon saiu do círculo da cibersegurança e já está nas mãos de quem assina o Google","c":"Se Atualize","d":"02 de outubro de 2026 (atualizado em 17 de outubro)","iso":"2026-10-02","s":"google-gemini-4-argon-lancamento-cyberseguranca","e":"O Gemini 4 Argon estreou em 30 de setembro restrito a defensores cibernéticos e, em 13 de outubro, chegou ao app Gemini para assinantes AI Pro e AI Ultra. API e free seguem com regras próprias.","min":3},{"t":"O Instagram quer que você comemore aniversário de amigo dentro do próprio app","c":"Se Atualize","d":"02 de outubro de 2026","iso":"2026-10-02","s":"instagram-university-novidades-criadores","e":"O Instagram anunciou efeito de aniversário no perfil e grupos de amigos próximos em teste, mirando engajamento de público mais jovem e retenção de criador.","min":1},{"t":"Uma nova plataforma quer tirar o artista independente da mão do Spotify de vez","c":"Se Atualize","d":"01 de outubro de 2026","iso":"2026-10-01","s":"even-studio-plataforma-direct-to-fan-artistas","e":"O EVEN STUDIO dá a cada artista um site próprio pra vender música, ingresso e produto, direto com o fã, sem passar pelo streaming. Venda qualificada já conta pra parada da Billboard.","min":1},{"t":"A Meta contratou o CEO da MongoDB pra tocar sua nova divisão de IA corporativa, e a ação da MongoDB despencou","c":"Se Atualize","d":"01 de outubro de 2026","iso":"2026-10-01","s":"meta-contrata-ceo-mongodb-ia-corporativa","e":"A Meta contratou o CEO da MongoDB, Chirantan Desai, pra tocar a nova divisão de IA corporativa. A ação da MongoDB caiu mais de 17% assim que a saída dele foi anunciada.","min":1},{"t":"A Nvidia lançou uma ferramenta pra impedir que agente de IA fuja do controle","c":"Se Atualize","d":"01 de outubro de 2026","iso":"2026-10-01","s":"nvidia-plataforma-seguranca-agentes-ia","e":"A Nvidia lançou uma plataforma de segurança com dois componentes, OpenShell e Sentry, pra impedir que agente de IA saia dos limites definidos em ambiente corporativo. Mais de 100 empresas já apoiam.","min":1},{"t":"A OpenAI lançou um agente que trabalha sozinho sem esperar comando, e já custa US$ 500 por mês","c":"Se Atualize","d":"01 de outubro de 2026","iso":"2026-10-01","s":"openai-devday-2026-dots-gpt-6-1-sol","e":"A OpenAI lançou o Dots, agente sempre ligado que trabalha sozinho rumo a um objetivo, e um novo modelo, o GPT-6.1 Sol. O plano mais caro pra acessar tudo isso já custa US$ 500 por mês.","min":2},{"t":"O Spotify saiu do ar pra mais de 36 mil usuários numa manhã de terça","c":"Se Atualize","d":"01 de outubro de 2026","iso":"2026-10-01","s":"spotify-instabilidade-saiu-do-ar-29-setembro","e":"O Spotify saiu do ar na manhã de 29/09 por cerca de uma hora, com mais de 36 mil relatos de problema. Login, busca e reprodução pararam de funcionar ao mesmo tempo.","min":1},{"t":"Zuckerberg, Amodei e Huang assinaram um pacto de segurança de IA que não pune ninguém","c":"Se Atualize","d":"01 de outubro de 2026","iso":"2026-10-01","s":"trump-executivos-ia-pacto-seguranca-voluntario","e":"Zuckerberg, Amodei, Huang e outros CEOs assinaram com Trump um pacto voluntário de segurança de IA. No dia seguinte, a FTC abriu investigação sobre Anthropic, OpenAI e outros laboratórios.","min":2},{"t":"A Apple foi obrigada a abrir a App Store no Brasil pra loja concorrente e pagamento externo","c":"Se Atualize","d":"28 de setembro de 2026","iso":"2026-09-28","s":"app-store-brasil-lojas-alternativas-cade","e":"Por acordo com o Cade, a Apple abriu a App Store no Brasil pra loja concorrente e pagamento externo, com comissão que varia de 5% a 21% dependendo do caminho que o desenvolvedor escolher.","min":2},{"t":"A Apple abriu uma casa de show em Londres, e quem estreia é Elton John","c":"Se Atualize","d":"28 de setembro de 2026","iso":"2026-09-28","s":"apple-music-hall-londres-elton-john","e":"A Apple abriu uma casa de show própria em Londres, dentro da Battersea Power Station, com Elton John estreando o espaço. A ideia é reforçar o Apple Music como marca de show ao vivo, não só streaming.","min":2},{"t":"Em menos de 200 dias, o anúncio do ChatGPT já fatura US$ 1 bilhão por ano","c":"Se Atualize","d":"28 de setembro de 2026","iso":"2026-09-28","s":"chatgpt-ads-1-bilhao-200-dias","e":"O ChatGPT Ads bateu US$ 1 bilhão de receita anualizada em menos de 200 dias, e a OpenAI já abriu autoatendimento em mais de 40 países. A briga por verba de anúncio com Google e Meta ficou séria rápido.","min":2},{"t":"A Meta uniu duas ferramentas de anúncio com criador numa só, e trouxe anúncio de live pro Instagram","c":"Se Atualize","d":"28 de setembro de 2026","iso":"2026-09-28","s":"meta-creator-marketing-hub-live-ads-instagram","e":"A Meta uniu duas ferramentas de anúncio com criador numa só, o Creator Marketing Hub, e passou a deixar transformar live de criador em Partnership Ad no Instagram.","min":2},{"t":"A Meta começou a cobrar até US$ 499 por mês por recursos que eram de graça","c":"Se Atualize","d":"28 de setembro de 2026","iso":"2026-09-28","s":"meta-one-assinatura-paga-empresas","e":"O Meta One cobra de US$ 2,99 a US$ 499 por mês por recursos que hoje são de graça, como agendamento de post e insights de concorrência. É a Meta monetizando de forma mais agressiva suas ferramentas de negócio.","min":2},{"t":"A música latina cresce mais que o mercado americano inteiro pela 13ª vez seguida","c":"Se Atualize","d":"28 de setembro de 2026","iso":"2026-09-28","s":"musica-latina-cresce-mais-mercado-eua-13-semestres","e":"A música latina faturou US$ 542,2 milhões nos EUA no 1º semestre de 2026, crescendo 8,6% e superando o mercado geral pela 13ª vez seguida. Streaming já é 96% dessa receita.","min":2},{"t":"O Spotify agora deixa você editar o próprio algoritmo de recomendação","c":"Se Atualize","d":"28 de setembro de 2026","iso":"2026-09-28","s":"spotify-taste-profile-editar-algoritmo","e":"O Taste Profile do Spotify mostra como o app entende seu gosto e deixa você pedir ajuste por linguagem natural. Já passou de testado na Nova Zelândia pra beta nos EUA.","min":2},{"t":"O projeto que taxa Netflix e Spotify no Brasil espera há quase um ano pra ser votado","c":"Se Atualize","d":"25 de setembro de 2026","iso":"2026-09-25","s":"pl-streaming-brasil-condecine-senado","e":"O PL 2331/2022 cobra Condecine e cota de conteúdo nacional de serviço de streaming como Netflix e Spotify. Aprovado na Câmara em novembro, segue parado no Senado há quase um ano.","min":2},{"t":"Agora dá pra montar playlist no Spotify batendo papo com a IA da Meta","c":"Se Atualize","d":"25 de setembro de 2026","iso":"2026-09-25","s":"spotify-integra-muse-meta-playlist-por-conversa","e":"O Spotify virou um dos primeiros serviços de música conectados ao Muse, o agente de IA pessoal da Meta. Dá pra tocar música, salvar faixa e montar playlist só de conversa.","min":1},{"t":"O Spotify agora monta playlist do setlist do show que você acabou de ver","c":"Se Atualize","d":"25 de setembro de 2026","iso":"2026-09-25","s":"spotify-reserved-share-cards-setlist","e":"O Reserved do Spotify ganhou share card personalizado, playlist automática do setlist do show e um espaço próprio dentro do app pra reunir tudo sobre o ingresso e o show.","min":1},{"t":"O YouTube lançou uma IA que transforma foto parada em personagem animado","c":"Se Atualize","d":"23 de setembro de 2026","iso":"2026-09-23","s":"youtube-made-on-youtube-2026-ia-anima-fotos","e":"No Made On YouTube 2026, o YouTube mostrou uma IA que transforma foto parada em personagem animado, deixou o selo de conteúdo feito com IA mais visível, e trouxe números novos de Shopping e TV.","min":2},{"t":"A OpenAI lançou anúncio dentro do ChatGPT que vira conversa com agente da marca","c":"Se Atualize","d":"21 de setembro de 2026","iso":"2026-09-21","s":"openai-chatgpt-ads-agentes-patrocinados","e":"A OpenAI testa anúncios no ChatGPT que abrem conversa direta com um agente de IA da marca. HubSpot e Shopify já são parceiras, e o movimento entra em rota de colisão com Google e Meta.","min":1},{"t":"Dois brasileiros entraram na turma mais internacional que o Foundry do YouTube Music já formou","c":"Se Atualize","d":"21 de setembro de 2026","iso":"2026-09-21","s":"youtube-music-foundry-class-2026-brasileiros","e":"O YouTube Music somou 16 artistas independentes de 8 países ao Foundry Class 2026, a turma mais global do programa até hoje. José Jr e Mariasss representam o Brasil dessa vez.","min":1},{"t":"OpenAI, Anthropic e Google, rivais diretos, estão negociando um pacto de segurança pra IA","c":"Se Atualize","d":"18 de setembro de 2026","iso":"2026-09-18","s":"openai-anthropic-google-pacto-seguranca-ia","e":"Os três maiores rivais da corrida de IA negociam desde julho um órgão comum de padrões de segurança. A conversa veio a público depois que o CEO da Anthropic pediu desaceleração num ensaio.","min":1},{"t":"O Spotify vai bancar estúdio de graça pra 10 mil artistas independentes por ano","c":"Se Atualize","d":"18 de setembro de 2026","iso":"2026-09-18","s":"spotify-fresh-finds-forward-artistas-independentes","e":"O Fresh Finds Forward do Spotify vai dar estúdio de graça, ferramenta profissional e acesso a parceria de turnê pra cerca de 10 mil artistas independentes emergentes por ano.","min":1},{"t":"O programa que paga podcaster no Spotify chegou no Brasil, na maior expansão da história dele","c":"Se Atualize","d":"18 de setembro de 2026","iso":"2026-09-18","s":"spotify-partner-program-chega-brasil","e":"O Spotify levou o Partner Program, que paga podcaster, pra mais de 35 novos países. No Brasil, abre em 19 de outubro, com exigência de 2 mil horas de audiência em 30 dias.","min":2},{"t":"A Apple criou exatamente o que Steve Jobs jurou que nunca faria","c":"Como Surgiu","d":"16 de setembro de 2026","iso":"2026-09-16","s":"como-surgiu-apple-music","e":"Steve Jobs disse por anos que ninguém ia querer pagar mensalidade pra ouvir música. A própria Apple lançou o Apple Music, exatamente o modelo que ele descartava.","min":2},{"t":"A DistroKid ficou de fora do pacto anti-fraude da música e agora enfrenta processo da Universal","c":"Se Atualize","d":"16 de setembro de 2026","iso":"2026-09-16","s":"distrokid-fora-pacto-anti-fraude-processo-universal","e":"Universal, Sony e Warner assinaram um pacto anti-fraude de streaming da IFPI. A DistroKid, que distribui 40% da música nova do mundo, ficou de fora, e na mesma semana foi processada pela Universal.","min":1},{"t":"A Anthropic pode abrir capital na maior oferta pública da história","c":"Se Atualize","d":"14 de setembro de 2026","iso":"2026-09-14","s":"anthropic-ipo-maior-oferta-historia","e":"Investidores da Anthropic esperam um IPO em outubro avaliado em até US$ 2 trilhões, superando até a SpaceX. Nada está fechado ainda, mas o crescimento de receita por trás da aposta é gigante.","min":1},{"t":"A nova IA de imagem da OpenAI ficou duas vezes mais rápida e mantém o rosto igual","c":"Se Atualize","d":"14 de setembro de 2026","iso":"2026-09-14","s":"openai-chatgpt-images-2-5-lancamento","e":"A OpenAI lançou o ChatGPT Images 2.5 com até 50% menos latência e muito mais fidelidade pra manter o rosto e o produto de referência em qualquer cenário gerado. Direto ao ponto pra quem cria peça de marketing com IA.","min":1},{"t":"Rock in Rio bateu recorde de público e já garantiu a próxima edição pra 2028","c":"Se Atualize","d":"14 de setembro de 2026","iso":"2026-09-14","s":"rock-in-rio-2026-recorde-publico","e":"Mais de 700 mil pessoas, R$ 3,36 bilhões de impacto econômico e mais de 100 ativações de marca em sete dias. O Rock in Rio 2026 bateu recorde e já confirmou a próxima edição pra 2028.","min":1},{"t":"A Universal pulou direto pro acordo com a IA que as outras majors estavam processando","c":"Se Atualize","d":"14 de setembro de 2026","iso":"2026-09-14","s":"universal-music-elevenlabs-acordo-ia","e":"Enquanto Sony e Warner processam a Anthropic, a Universal fechou acordo de anos com a ElevenLabs pra construir uma plataforma de remix por IA com os artistas participando de forma licenciada, sem processo nenhum.","min":1},{"t":"O Weverse vazou dados de 422 mil contas, a segunda vez este ano","c":"Se Atualize","d":"14 de setembro de 2026","iso":"2026-09-14","s":"weverse-vazamento-dados-422-mil-contas","e":"A Weverse confirmou vazamento de dados de 422.584 contas por falha numa API de pagamento, a segunda falha de segurança da empresa em 2026. Nomes, contato e número de cartão não foram expostos.","min":1},{"t":"A Concord sumiu do nome, mas o CEO dela ficou no comando da nova gigante da música","c":"Se Atualize","d":"11 de setembro de 2026","iso":"2026-09-11","s":"bmg-concord-fusao-ceo-concord","e":"Bob Valentine era CEO da Concord. Depois que a fusão com a BMG saiu do papel em 1º de setembro, ele ficou no comando da empresa combinada, que opera sob o nome BMG e reúne mais de 4 milhões de obras.","min":1},{"t":"Jason Isbell processa a Suno, e o motivo não é direito autoral","c":"Se Atualize","d":"11 de setembro de 2026","iso":"2026-09-11","s":"jason-isbell-processa-suno-nao-e-direito-autoral","e":"Jason Isbell, David Lowery e outros artistas entraram com ação coletiva contra a Suno. O processo não fala de música copiada, fala de voz e identidade usadas sem consentimento.","min":2},{"t":"Sony e Warner processam a Anthropic por usar dezenas de milhares de músicas pra treinar a Claude","c":"Se Atualize","d":"11 de setembro de 2026","iso":"2026-09-11","s":"sony-warner-processam-anthropic-claude","e":"Sony Music Publishing e Warner Chappell processam a Anthropic e alegam uma campanha de pirataria em massa pra treinar o Claude. A indenização pedida pode passar de bilhões de dólares.","min":2},{"t":"A diferença de 40 bilhões de dólares entre decidir com medo e decidir com clareza","c":"Nota Mental #4","d":"10 de setembro de 2026","iso":"2026-09-10","s":"decidir-com-medo-ou-com-clareza","e":"Em 2007 a Netflix apostou no streaming com o DVD ainda lucrativo. Em 2008 o Yahoo recusou uma oferta de 44,6 bilhões de dólares e, oito anos depois, vendeu por menos de um décimo disso. A diferença entre as duas decisões não foi informação, foi clareza.","min":3},{"t":"O Marco Legal da IA no Brasil perdeu a quinta data de votação seguida","c":"Se Atualize","d":"09 de setembro de 2026","iso":"2026-09-09","s":"marco-legal-ia-brasil-atraso-camara","e":"O PL 2338/2023, que regula o uso de inteligência artificial no Brasil, segue parado numa comissão especial da Câmara há 16 meses. Em 7 de setembro, o status oficial era o mesmo de sempre: aguardando parecer do relator.","min":3},{"t":"O Meta AI agora lê seu Gmail, Docs e Planilhas pra otimizar seus anúncios","c":"Se Atualize","d":"09 de setembro de 2026","iso":"2026-09-09","s":"meta-ai-conecta-google-workspace-anuncios","e":"Desde 19 de agosto, o Meta AI pode acessar Gmail, Google Docs, Planilhas e Slides de quem anuncia no Facebook e Instagram pra gerar relatório e sugerir ajuste de campanha sozinho. Veja o que muda pra quem faz tráfego pago.","min":1},{"t":"O novo CEO da Apple estreou lançando o primeiro iPhone dobrável da história","c":"Se Atualize","d":"09 de setembro de 2026","iso":"2026-09-09","s":"novo-ceo-apple-iphone-dobravel","e":"Tim Cook deixou o comando da Apple em 1º de setembro depois de 15 anos. Oito dias depois, o novo CEO John Ternus subiu ao palco pela primeira vez pra lançar o iPhone 18 Pro e o primeiro iPhone dobrável da história.","min":1},{"t":"YouTube quase foi um app de paquera","c":"Como Surgiu","d":"09 de setembro de 2026","iso":"2026-09-09","s":"youtube-quase-foi-site-de-paquera","e":"O YouTube nasceu como um site de paquera em vídeo, com o slogan 'Tune In, Hook Up'. Quase ninguém usou do jeito planejado, e foi o ajuste não planejado que virou a plataforma bilionária que a gente conhece hoje.","min":2},{"t":"Time bom não é o que nunca erra, é o que corrige rápido sem drama","c":"Nota Mental #3","d":"07 de setembro de 2026","iso":"2026-09-07","s":"time-bom-corrige-sem-drama","e":"Em 2012, o CEO da Apple mandou os próprios clientes usarem o mapa do concorrente. Em 2017, um comando digitado errado na Amazon derrubou boa parte da internet por 4h17. Duas empresas, dois erros públicos, o mesmo motivo pra vencerem depois.","min":2},{"t":"Radar da Semana: a IA caiu no mesmo dia em que lançou o modelo mais avançado da história","c":"Resumo da Semana","d":"04 de setembro de 2026","iso":"2026-09-04","s":"radar-da-semana-04-09","e":"BMG e Concord criam a quarta major da música, Sony e Warner Chappell processam a Anthropic, a OpenAI lança o GPT-6 Astra, e no mesmo dia ChatGPT, Claude e Grok saem do ar juntos por 5 horas.","min":1},{"t":"Todo negócio bom nasceu de alguém que se incomodou com algo malfeito","c":"Pensa Nisso #5","d":"03 de setembro de 2026","iso":"2026-09-03","s":"incomodo-malfeito-vira-negocio","e":"Numa antiga agência, o time presencial rendia pouco mesmo com estrutura boa. Três designers remotos renderam mais que o time inteiro. Foi esse incômodo que virou o método que sustenta a ALKA até hoje.","min":1},{"t":"Spotify: nasceu pra matar a pirataria, e um cofundador do Napster ajudou a bancar","c":"Como Surgiu","d":"02 de setembro de 2026","iso":"2026-09-02","s":"spotify-nasceu-pra-matar-pirataria","e":"Fundado em 2006 com as gravadoras como sócias, o nome que virou lenda tem origem inventada, e um dos primeiros investidores foi cofundador do Napster. Cinco curiosidades por trás do maior serviço de streaming do mundo.","min":1},{"t":"Forró ganha categoria própria no PMB","c":"Avulso","d":"31 de agosto de 2026","iso":"2026-08-31","s":"forro-categoria-propria-pmb","e":"Depois de décadas entrando como sertanejo, o forró ganhou categoria própria no Prêmio da Música Brasileira, por campanha de João Gomes em homenagem a Luiz Gonzaga.","min":1},{"t":"Não são os mais fortes que sobrevivem","c":"Pensa Nisso #4","d":"28 de agosto de 2026","iso":"2026-08-28","s":"nao-sao-os-mais-fortes-que-sobrevivem","e":"A Blockbuster riu de uma proposta de comprar a Netflix por 50 milhões de dólares. A Kodak inventou a câmera digital e engavetou por décadas. As duas tinham tudo, menos velocidade.","min":1},{"t":"As ferramentas que você usa todo dia mudaram de função","c":"Se Atualize","d":"27 de agosto de 2026","iso":"2026-08-27","s":"ferramentas-mudaram-de-funcao","e":"O Instagram passou a pagar por carrossel, o WhatsApp virou vendedor cobrado pela Meta, e Suno e Anthropic foram processadas no mesmo dia. Quem lê a mudança primeiro decide na frente, não atrás.","min":2},{"t":"Você não precisa ver o topo","c":"Pensa Nisso #3","d":"24 de agosto de 2026","iso":"2026-08-24","s":"voce-nao-precisa-ver-o-topo","e":"Pediram a capa de uma banda, ele achou feia e disse que fazia melhor. Não tinha curso nem plano, só resolveu aquele problema ali. Anos depois estava competindo com agência inteira do Nordeste.","min":1},{"t":"O YouTube vai mudar como conta suas visualizações","c":"Avulso","d":"22 de agosto de 2026","iso":"2026-08-22","s":"youtube-visualizacao-engajada","e":"A partir de 24 de agosto de 2026, toda view no YouTube passa a contar desde o primeiro quadro. O critério antigo ganhou nome novo: Visualização Engajada, e é ela que continua valendo pra monetização.","min":1},{"t":"Os 3 A's da vida","c":"Pensa Nisso #2","d":"21 de agosto de 2026","iso":"2026-08-21","s":"tres-as-da-vida","e":"Acreditar, arriscar e alcançar parecem uma sequência simples, mas cada etapa cobra um preço diferente.","min":1},{"t":"Esperar a oportunidade pode travar uma empresa","c":"Nota Mental #1","d":"20 de agosto de 2026","iso":"2026-08-20","s":"esperar-oportunidade-trava-empresa","e":"Spotify, Nubank e ALKA começaram quando alguém decidiu agir sobre um problema, em vez de esperar a oportunidade chegar pronta.","min":1},{"t":"As oportunidades não acontecem, você as cria","c":"Pensa Nisso #1","d":"19 de agosto de 2026","iso":"2026-08-19","s":"oportunidades-nao-acontecem-voce-cria","e":"Spotify e Nubank não esperaram o mercado mudar sozinho. Criaram a mudança. Com a ALKA não foi diferente.","min":1},{"t":"Contrato vale mais que medo","c":"Se Atualize","d":"17 de agosto de 2026","iso":"2026-08-17","s":"contrato-vale-mais-que-medo","e":"Deezer, Suno e Spotify assinaram contrato, criaram regra e dividiram o dinheiro enquanto todo mundo discutia se a IA ia acabar com a música. O mercado musical vai crescer quase 63% até 2033, e quem não assinar primeiro perde a parte que era sua.","min":3},{"t":"Viral não é o mesmo que ser pago","c":"Se Atualize","d":"03 de agosto de 2026","iso":"2026-08-03","s":"viral-nao-e-o-mesmo-que-ser-pago","e":"O Deezer recebe 60 mil músicas por dia feitas por IA, quase 4 em cada 10 uploads. O TIDAL respondeu cortando royalty de faixas 100% sintéticas. Dominar o viral não é o mesmo que virar artista de verdade.","min":3}];
